// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TestTodo) predicate.TestTodo {
	return predicate.TestTodo(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TestTodo) predicate.TestTodo {
	return predicate.TestTodo(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TestTodo) predicate.TestTodo {
	return predicate.TestTodo(sql.NotPredicates(p))
}
